'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import {readFinancialPostingReview,type FinancialAccounts} from '@/lib/financial-migration-posting';
import {validateReconciliationRequest,type ReconciliationRequest} from '@/lib/financial-reconciliation';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {FinancialReconciliationDecisions} from './financial-reconciliation-decisions';
import {FinancialReconciledPosting} from './financial-reconciled-posting';
import {FinancialUnifiedWorkflow} from './financial-unified-workflow';
import {validateUnifiedSaveRequest} from '@/lib/financial-unified-save';
import {FinancialSplitWorkflow} from './financial-split-workflow';
import {validateSplitSaveRequest} from '@/lib/financial-split-save';
type Props={scope:HandoffScope;batch:string;onCompleted:()=>void;onRecoveryLock?:(locked:boolean)=>void};
export function FinancialReconciliationWorkflow(p:Props){return <Workflow key={[p.scope.tenant,p.scope.property,p.scope.actor,p.batch].join(':')} {...p}/>}
function Workflow({scope,batch,onCompleted,onRecoveryLock}:Props){
 const [mode,setMode]=useState<'whole'|'split'|'unified'>('whole');
 const [setup,setSetup]=useState<AccountingSetup|null>(null),[accounts,setAccounts]=useState<FinancialAccounts>({receivable:'',prepayment:'',security:'',offset:''}),[period,setPeriod]=useState(''),[assessment,setAssessment]=useState<Record<string,unknown>|null>(null),[requestId,setRequestId]=useState(''),[saved,setSaved]=useState<ReconciliationRequest|null>(null),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[recovery,setRecovery]=useState(false),[error,setError]=useState('');
 const alive=useRef(false),lock=useRef(false),suffix=[scope.tenant,scope.property,scope.actor,batch].join(':'),readyKey='irp.reconciliation.ready.v1:'+suffix;
 useEffect(()=>{alive.current=true;try{const post=sessionStorage.getItem('irp.reconciled.post.v1:'+suffix),save=sessionStorage.getItem('irp.reconciliation.save.v1:'+suffix),stored=sessionStorage.getItem(readyKey);const r=post?JSON.parse(post).reconciliation:save?JSON.parse(save):stored?JSON.parse(stored):null;
  const splitPost=sessionStorage.getItem('irp.split.post.v1:'+suffix),splitSave=sessionStorage.getItem('irp.split.save.v1:'+suffix),splitReady=sessionStorage.getItem('irp.split.ready.v1:'+suffix);const split=splitPost?JSON.parse(splitPost).reconciliation:splitSave?JSON.parse(splitSave):splitReady?JSON.parse(splitReady):null;
  const unifiedPost=sessionStorage.getItem('irp.unified.post.v1:'+suffix),unifiedSave=sessionStorage.getItem('irp.unified.save.v1:'+suffix),unifiedReady=sessionStorage.getItem('irp.unified.ready.v1:'+suffix);const unified=unifiedPost?JSON.parse(unifiedPost).reconciliation:unifiedSave?JSON.parse(unifiedSave):unifiedReady?JSON.parse(unifiedReady):null;
  if((post!==null||save!==null||stored!==null)&&!r||(splitPost!==null||splitSave!==null||splitReady!==null)&&!split||(unifiedPost!==null||unifiedSave!==null||unifiedReady!==null)&&!unified)throw Error('Saved migration request is incomplete. Keep it for recovery before continuing.');
  if([r,split,unified].filter(Boolean).length>1)throw Error('Two migration workflows need recovery. Resolve saved requests before continuing.');
  if(unified){validateUnifiedSaveRequest(unified);if(unified.scope.tenant!==scope.tenant||unified.scope.property!==scope.property||unified.scope.actor!==scope.actor||unified.batch!==batch)throw Error('Stored combined migration belongs to another workspace.');const p=unified.review.assessment.posting_review;setMode('unified');setAccounts(p.account_mapping);setPeriod(p.period.id);setAssessment(unified.review.assessment);}
  if(split){validateSplitSaveRequest(split);const s=split.selection;if(s.scope.tenant!==scope.tenant||s.scope.property!==scope.property||s.scope.actor!==scope.actor||s.batch!==batch)throw Error('Saved split migration belongs to another workspace.');setMode('split');setAccounts(s.accounts);setPeriod(s.period);setAssessment(split.assessment);setRequestId(split.id);}
  if(r){validateReconciliationRequest(r);if(r.selection.scope.tenant!==scope.tenant||r.selection.scope.property!==scope.property||r.selection.scope.actor!==scope.actor||r.selection.batch!==batch)throw Error('Saved reconciliation belongs to another workspace.');setAccounts(r.selection.accounts);setPeriod(r.selection.period);if(post||!save)setSaved(r);else{setAssessment(r.assessment);setRequestId(r.id)}}setReady(true);
 }catch(e){setError(e instanceof Error?e.message:'Unable to restore migration.')}return()=>{alive.current=false}},[suffix]);
 useEffect(()=>{onRecoveryLock?.(!ready||busy||recovery)},[ready,busy,recovery,onRecoveryLock]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen migration.');}
 async function load(kind:'setup'|'preview'){if(lock.current||!ready||recovery||saved)return;lock.current=true;setBusy(true);setError('');try{await identify();if(kind==='setup'){const value=readAccountingSetup(await hotelRpc('gl_setup',{p_tenant:scope.tenant,p_property:scope.property}),scope.tenant,scope.property);await identify();if(alive.current)setSetup(value)}else{const value=await hotelRpc<Record<string,unknown>>('preview_financial_migration_reconciliation',{p_tenant:scope.tenant,p_property:scope.property,p_batch:batch,p_period:period,p_accounts:accounts});readFinancialPostingReview(value.posting_review,{scope,batch,period,accounts});await identify();if(alive.current){setAssessment(value);setRequestId(crypto.randomUUID())}}}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to review migration.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 function accept(r:ReconciliationRequest){sessionStorage.setItem(readyKey,JSON.stringify(r));setSaved(r);setAssessment(null)}
 function completed(){sessionStorage.removeItem(readyKey);onCompleted()}
 function restart(){sessionStorage.removeItem(readyKey);setSaved(null);setAssessment(null);setRequestId('');setRecovery(false);setError('')}
 return <section className="card"><h2>Reconcile opening balances</h2>{saved?<FinancialReconciledPosting saved={saved} onCompleted={completed} onCancelled={restart} onRecoveryLock={setRecovery}/>:<><button type="button" disabled={!ready||busy||recovery} onClick={()=>void load('setup')}>Load opening accounts and periods</button><fieldset disabled={!ready||busy||recovery}><label className="field">Balance reconciliation method<select value={mode} onChange={e=>{setMode(e.target.value as 'whole'|'split'|'unified');setAssessment(null)}}><option value="whole">Match each entire source balance</option><option value="unified">Match invoices and deposits, or add balances</option><option value="split">Split balances between invoices and new balances</option></select></label>{(['receivable','prepayment','security','offset'] as const).map(category=><label className="field" key={category}>{category==='offset'?'Opening balance offset account':`${category[0].toUpperCase()+category.slice(1)} account`}<select value={accounts[category]} onChange={e=>{setAccounts({...accounts,[category]:e.target.value});setAssessment(null)}}><option value="">Choose account</option>{setup?.accounts.filter(a=>a.active&&a.kind===(category==='receivable'?'asset':category==='offset'?'equity':'liability')).map(a=><option key={a.account_id} value={a.account_id}>{a.code} {a.name}</option>)}</select></label>)}<label className="field">Opening accounting period<select value={period} onChange={e=>{setPeriod(e.target.value);setAssessment(null)}}><option value="">Choose period</option>{setup?.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to {p.end_date_exclusive}</option>)}</select></label></fieldset><button type="button" disabled={!ready||busy||recovery||!period||Object.values(accounts).some(v=>!v)} onClick={()=>void load('preview')}>Preview source reconciliation</button>{assessment&&mode==='unified'&&<FinancialUnifiedWorkflow selection={{scope,batch,period,accounts}} assessment={assessment} onCompleted={completed} onRecoveryLock={setRecovery}/>} {assessment&&mode==='split'&&<FinancialSplitWorkflow selection={{scope,batch,period,accounts}} assessment={assessment} onCompleted={completed} onRecoveryLock={setRecovery}/>} {assessment&&mode==='whole'&&<FinancialReconciliationDecisions key={requestId} selection={{scope,batch,period,accounts}} assessment={assessment} requestId={requestId} onSaved={accept} onCancelled={restart} onRecoveryLock={setRecovery}/>}</>}{error&&<p role="alert">{error}</p>}</section>;
}
